<script setup>
import { onMounted, onUnmounted, ref } from 'vue'
import SiteHeader from '../components/common/SiteHeader.vue'
import JoinSpaceForm from '../components/common/JoinSpaceForm.vue'
import { account, accountLoading, loadAccount } from '../services/account.js'
import { currentUser } from '../services/auth.js'
import { toast } from '../services/toast.js'
import api from '../services/api.js'
import { copyRoomInvite } from '../services/roomInvite.js'
const rooms=ref([]),roomsLoading=ref(false)
const reminded=new Set()
let reminderTimer, roomRefreshTimer
async function loadRooms(){roomsLoading.value=true;try{rooms.value=(await api.get('/rooms/mine')).data.data || [];remind()}catch(error){toast.error(error)}finally{roomsLoading.value=false}}
async function refresh(){try{await loadAccount(true);await loadRooms()}catch(error){toast.error(error)}}
function when(ms){return new Intl.DateTimeFormat('id-ID',{dateStyle:'full',timeStyle:'short'}).format(new Date(ms))}
function remind(){const now=Date.now();for(const room of rooms.value){if(!room.nextAt)continue;const remaining=room.nextAt-now;const key=`${room.id}:${room.nextAt}`;if(remaining>=0&&remaining<=15*60_000&&!reminded.has(key)){reminded.add(key);toast.info(`${room.name} dimulai dalam ${Math.ceil(remaining/60_000)} menit.`)}}}
function calendarUrl(id){return `${api.defaults.baseURL}/rooms/${encodeURIComponent(id)}/calendar.ics`}
async function copyCalendarLink(id){try{await navigator.clipboard.writeText(calendarUrl(id));toast.success('Tautan kalender tersalin.')}catch(error){toast.error(error)}}
onMounted(()=>{void refresh();reminderTimer=setInterval(remind,60_000);roomRefreshTimer=setInterval(loadRooms,10*60_000)})
onUnmounted(()=>{clearInterval(reminderTimer);clearInterval(roomRefreshTimer)})
</script>
<template><SiteHeader /><main class="account-page"><span class="ms-badge">KARTU ANGGOTA</span><h1>Selamat datang di klub.</h1><p class="ms-muted">{{currentUser?.email}}</p>
  <section class="membership ms-card"><div class="membership-mark" aria-hidden="true">✦</div><div><span class="status-label">{{accountLoading?'Memeriksa akses…':!account?'Status belum tersedia':account.access==='full'?'AKSES PENUH AKTIF':'AKSES PESERTA AKTIF'}}</span><h2>{{!account?'Aksesmu belum dapat diperiksa.':account.access==='full'?'Ruang berikutnya, milikmu.':'Kamu sudah bisa bergabung.'}}</h2><p>{{!account?'Coba periksa akses lagi. Jika tetap gagal, hubungi admin.':account.access==='full'?'Buat room, undang teman, dan gunakan tools host yang tersedia.':'Gunakan undangan untuk mengikuti meeting. Untuk membuat room sendiri, admin perlu mengaktifkan akses penuh akunmu.'}}</p><div class="account-actions"><RouterLink v-if="account?.access==='full'" to="/create-room" class="ms-button ms-button-accent">Buat room ↗</RouterLink><button v-else class="ms-button ms-button-primary" :disabled="accountLoading" @click="refresh">{{accountLoading?'Memeriksa…':'Periksa akses lagi ↻'}}</button><RouterLink v-if="account?.role==='admin'" to="/admin" class="ms-button ms-button-outline">Dashboard admin ▦</RouterLink></div></div></section>
  <section class="account-bottom"><div class="ms-card join-card"><JoinSpaceForm /></div><div class="access-note"><h3>Aksesmu, jelas dari awal.</h3><p>Pendaftaran terbuka untuk semua orang. Admin melihat akun yang baru terdaftar dan dapat memberikan akses penuh.</p><p>Jika akses host dicabut, pembuatan room dan sesi host baru akan ditolak. Sesi yang sedang berjalan tidak otomatis terputus.</p></div></section>
  <section v-if="account?.access==='full'" class="my-rooms ms-card"><div class="rooms-head"><div><span class="ms-badge">KALENDER KLUB</span><h2>Room milikmu</h2><p>Link tetap untuk rapat berulang; peserta tetap melalui approval. Undangan kalender mengingatkan 15 menit sebelumnya.</p></div><button class="ms-button ms-button-outline" :disabled="roomsLoading" @click="loadRooms">{{roomsLoading?'Memuat…':'Refresh ↻'}}</button></div><div v-for="room in rooms" :key="room.id" class="room-row"><div><strong>{{room.name}}</strong><small>{{room.schedule?`${room.nextAt?when(room.nextAt):'Jadwal berlalu'} · ${room.schedule.repeat==='weekly'?'Tiap minggu':'Sekali'}`:'Room tanpa jadwal'}}</small><small>Meeting ID {{room.meetingId}}</small></div><div><RouterLink class="ms-button ms-button-primary" :to="{name:'lobby',params:{roomId:room.id}}">Buka room ↗</RouterLink><button class="ms-button ms-button-outline" @click="copyRoomInvite(room.id)">Salin undangan</button><a v-if="room.schedule" class="ms-button ms-button-outline" :href="calendarUrl(room.id)">Unduh kalender</a><button v-if="room.schedule" class="ms-button ms-button-outline" @click="copyCalendarLink(room.id)">Salin link kalender</button></div></div><p v-if="!rooms.length">{{roomsLoading?'Memuat room…':'Belum ada room aktif. Buat room untuk memulai.'}}</p></section>
</main></template>
<style scoped>.my-rooms{padding:28px;margin-top:28px}.rooms-head,.room-row,.room-row>div:last-child{display:flex;justify-content:space-between;align-items:center;gap:14px}.rooms-head h2{margin:12px 0 4px}.rooms-head p,.my-rooms>p{font-size:12px;color:var(--text-secondary)}.room-row{padding:15px 0;border-top:1px dashed var(--border-color)}.room-row>div:first-child{display:grid;gap:4px}.room-row small{font-size:11px;color:var(--text-secondary)}.room-row .ms-button{font-size:11px;white-space:nowrap}@media(max-width:700px){.rooms-head,.room-row{align-items:start;flex-direction:column}.room-row>div:last-child{flex-wrap:wrap}}</style>
<style scoped>
.account-page{width:min(1040px,calc(100% - 40px));margin:55px auto 80px}h1{font-size:clamp(36px,5vw,55px);margin:20px 0 10px}.membership{display:grid;grid-template-columns:130px 1fr;gap:35px;padding:42px;margin-top:30px}.membership-mark{width:120px;height:120px;border:2px solid var(--border-color);border-radius:50%;background:var(--color-secondary);color:#292e29;display:grid;place-items:center;font-size:75px;box-shadow:5px 5px 0 var(--shadow-color)}.status-label{font-size:11px;font-weight:1000;letter-spacing:2px;color:var(--text-secondary)}h2{font-size:31px;margin:12px 0}.membership p,.access-note p{color:var(--text-secondary);font-size:15px;line-height:1.8}.account-actions{display:flex;gap:15px;flex-wrap:wrap;margin-top:25px}.account-bottom{display:grid;grid-template-columns:1fr 1fr;gap:40px;margin-top:40px}.join-card{padding:30px;align-self:start}.access-note h3{margin-top:0;font-size:25px}@media(max-width:700px){.membership,.account-bottom{grid-template-columns:1fr}.membership{padding:28px;gap:25px}.membership-mark{width:75px;height:75px;font-size:45px}.account-page{margin-top:35px}}
</style>
